command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "118b92c77c5ca8a78207b5236c42fa688796d108") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "3984884008f30f67434efaa5c963b68c565f79c2") { throw "work branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout work branch failed" }
git merge --no-edit origin/main
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "main merge conflicted" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed after merge" }
$newHead=(git rev-parse HEAD).Trim()
Write-Host ("INTEGRATED_HEAD=" + $newHead)
git push origin HEAD:refs/heads/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "push integrated work branch failed" }
Write-Host "LARGE_FOLDER_NAME_INDEX_MAIN_INTEGRATION_PASS"
